import json
from pathlib import Path

ROS=Path('/home/zhuyulab/ns3-workspace/ros2_ws/ros2-multi-robot-automap')
record=json.loads(Path('/tmp/p3b5_v88_development_declaration.json').read_text())
print(json.dumps(dict(scope='six independent development originals',owners=[(r['plan']['name'],r.get('returncode','live')) for r in record['executions']],finished=record.get('finished_at_utc'))))
counts=dict(raw=0,true_rally_complete=0,partial=0,contacts=0,infrastructure=0)
for name in ('zero','forced','returnproof','lab','rooms','corridors','holdout','safety'):
    root=ROS/'log/p3b5'/('p3b5_v88_dev_'+name)
    path=root/'summary.json'
    if not path.exists():continue
    summary=json.loads(path.read_text())
    active=[];done=[]
    for directory in sorted(root.iterdir()):
        if not directory.is_dir():continue
        identity=directory.name;result=directory/(identity+'.json')
        if result.exists():
            r=json.loads(result.read_text());counts['raw']+=1;counts['contacts']+=r['collision_events']
            counts['true_rally_complete']+=bool(r['mission_mode']=='rally' and r['success'] and r['task_phase']=='COMPLETE' and r['native_rally_hold_proof'])
            counts['partial']+=bool(r['partial_completion'])
            done.append(dict(episode=identity,mode=r['mission_mode'],phase=r['task_phase'],success=r['success'],completion=r['completion_time_sec'],duration=r['elapsed_sim_time_sec'],charges=r['battery_total_charges'],min_energy=r['battery_minimum_energy'],contacts=r['collision_events']))
        else:
            epoch=None;latest=None;phase=None;batteries={}
            ledger=directory/'ledger.jsonl'
            if ledger.exists():
                for line in ledger.open():
                    e=json.loads(line)
                    if e['event']=='fault_epoch':epoch=e['event_time'];break
                with ledger.open('rb') as stream:
                    stream.seek(max(0,ledger.stat().st_size-30000));lines=stream.read().splitlines()
                for line in reversed(lines):
                    try:
                        e=json.loads(line);latest=e.get('time',e.get('event_time'))
                        if latest is not None:break
                    except json.JSONDecodeError:pass
            events=directory/'safety_events.jsonl'
            if events.exists():
                for line in events.open():
                    try:e=json.loads(line)
                    except json.JSONDecodeError:continue
                    if e['topic']=='/task_state':phase=e['data']
                    if e['topic'].endswith('/battery_state'):
                        b=e['data'];batteries[b['robot']]=dict(last_transition_mode=b['mode'],charges=b['charge_count'])
            active.append(dict(episode=identity,phase=phase,ledger_offset_sec=None if epoch is None or latest is None else round(latest-epoch,1),battery_transitions=batteries))
    counts['infrastructure']+=sum(bool(row['infrastructure_failure']) for row in summary['episodes'].values())
    print(json.dumps(dict(pool=name,finished=summary.get('finished_at_utc'),done=done,active=active)))
for ledger in sorted((ROS/'log/p2d_baseline').glob('p3b5_v88_dev_fixed_*/episodes/*_ledger.jsonl')):
    result=ledger.with_name(ledger.name.replace('_ledger.jsonl','.json'))
    if result.exists():continue
    epoch=None
    for line in ledger.open():
        try:e=json.loads(line)
        except json.JSONDecodeError:continue
        if e['event']=='fault_epoch':epoch=e['event_time'];break
    with ledger.open('rb') as stream:
        stream.seek(max(0,ledger.stat().st_size-40000));lines=stream.read().splitlines()
    latest=None;phase=None
    for line in reversed(lines):
        try:e=json.loads(line)
        except json.JSONDecodeError:continue
        if latest is None:latest=e.get('time',e.get('event_time'))
        if phase is None:phase=e.get('task_phase')
        if latest is not None and phase is not None:break
    print(json.dumps(dict(active_fixed=ledger.name,phase=phase,ledger_offset_sec=None if epoch is None or latest is None else round(latest-epoch,1))))
for path in sorted((ROS/'log/p2d_baseline').glob('p3b5_v88_dev_fixed_*/summary.json')):
    s=json.loads(path.read_text());rows=[]
    for row in s['episodes']:
        r=json.loads(Path(row['result_path']).read_text());counts['raw']+=1;counts['contacts']+=r['collision_events'];counts['infrastructure']+=bool(row['infrastructure_failure'])
        genuine=bool(r['success'] and r['task_phase']=='COMPLETE' and r['native_rally_hold_proof']);counts['true_rally_complete']+=genuine
        rows.append(dict(world=r['world_file'],robots=row['robot_count'],seed=row['gazebo_seed'],success=genuine,completion=r['completion_time_sec'],phase=r['task_phase'],contacts=r['collision_events']))
    print(json.dumps(dict(fixed_pool=path.parent.name,rows=rows)))
print(json.dumps(dict(counts=counts)))

